<script setup lang="ts">
// 顶部「模式状态条」：常驻所有 tab，一眼回答「系统在不在跑、以什么模式跑、预算还剩多少」。
// 数据来自总览（预算/心跳）与 worker 配置接口（生效设置 + judge 真实心跳）。
// 限额与运行参数都可以直接在这里改（弹窗），worker 下一轮 tick 即生效，无需重启 judge。
import { computed } from "vue";
import { fmtAgo } from "./enrich-common";
import type { EnrichOverview, EnrichWorkerConfig } from "@/types/problem-enrichment";

const props = defineProps<{
  overview: EnrichOverview | null;
  workerConfig: EnrichWorkerConfig | null;
}>();

const emit = defineEmits<{
  (e: "open-settings"): void;
}>();

// 运行状态：未启用 > 等待心跳 > 自动运行中
const mode = computed<{
  label: string;
  theme: string;
  desc: string;
} | null>(() => {
  const cfg = props.workerConfig;
  if (!cfg) {
    return null;
  }
  const settings = cfg.settings;
  const heartbeat = cfg.heartbeat;
  if (!settings.enabled) {
    return {
      label: "已停用",
      theme: "default",
      desc: "worker 已停用，不认领任何题目；点「运行参数」打开即可重新启用",
    };
  }
  if (!heartbeat?.heartbeat_time) {
    return {
      label: "等待 worker 心跳",
      theme: "warning",
      desc: "judge 进程未部署或尚未跑过一轮，后台暂无真实运行参数",
    };
  }
  return {
    label: "自动运行中",
    theme: "success",
    desc: "worker 每轮自动回收卡死题并批量认领待处理题目，受每日限额约束；人工重判不受限额限制",
  };
});

const tokenPct = computed(() => {
  const b = props.overview?.budget;
  if (!b || b.token_limit <= 0) {
    return 0;
  }
  return Math.min(100, Math.round((b.token_used / b.token_limit) * 100));
});

const problemPct = computed(() => {
  const b = props.overview?.budget;
  if (!b || b.problem_limit <= 0) {
    return 0;
  }
  return Math.min(100, Math.round((b.problem_used / b.problem_limit) * 100));
});

const fmtNum = (n: number): string => {
  if (n >= 1_000_000) {
    return `${(n / 1_000_000).toFixed(1)}M`;
  }
  if (n >= 1_000) {
    return `${(n / 1_000).toFixed(1)}k`;
  }
  return String(n);
};
</script>

<template>
  <div v-if="overview" class="mode-bar">
    <!-- 运行状态 -->
    <t-tooltip :content="mode?.desc || ''">
      <t-tag v-if="mode" :theme="mode.theme" variant="light" class="mode-item">
        {{ mode.label }}
      </t-tag>
    </t-tooltip>

    <!-- 运行参数与限额（弹窗编辑，worker 下一轮生效） -->
    <t-button size="small" variant="outline" @click="emit('open-settings')">运行参数与限额</t-button>

    <!-- worker 心跳 -->
    <t-tag
      v-if="overview.worker.heartbeat_time"
      :theme="overview.worker.alive ? 'success' : 'danger'"
      variant="outline"
      class="mode-item"
    >
      worker 心跳 {{ fmtAgo(overview.worker.heartbeat_time) }}
      {{ overview.worker.alive ? "" : "（已离线）" }}
    </t-tag>
    <t-tag v-else theme="warning" variant="outline" class="mode-item">worker 无心跳</t-tag>

    <!-- 今日预算（限额只拦自动批量，人工重判不占额度） -->
    <t-tooltip
      :content="`今日已消耗 token ${overview.budget.token_used.toLocaleString()} / ${overview.budget.token_limit > 0 ? overview.budget.token_limit.toLocaleString() : '不限'}`"
    >
      <span class="mode-budget">
        <span class="mode-budget-label">token</span>
        <span class="mode-budget-bar">
          <span
            class="mode-budget-fill"
            :class="{ 'mode-budget-danger': tokenPct >= 90 }"
            :style="{ width: `${tokenPct}%` }"
          />
        </span>
        <span class="mode-budget-text">
          {{ fmtNum(overview.budget.token_used) }}/{{ overview.budget.token_limit > 0 ? fmtNum(overview.budget.token_limit) : "∞" }}
        </span>
      </span>
    </t-tooltip>
    <t-tooltip
      :content="`今日已审阅题目 ${overview.budget.problem_used} / ${overview.budget.problem_limit > 0 ? overview.budget.problem_limit : '不限'}`"
    >
      <span class="mode-budget">
        <span class="mode-budget-label">题数</span>
        <span class="mode-budget-bar">
          <span
            class="mode-budget-fill"
            :class="{ 'mode-budget-danger': problemPct >= 90 }"
            :style="{ width: `${problemPct}%` }"
          />
        </span>
        <span class="mode-budget-text">
          {{ overview.budget.problem_used }}/{{ overview.budget.problem_limit > 0 ? overview.budget.problem_limit : "∞" }}
        </span>
      </span>
    </t-tooltip>
  </div>
</template>

