<script setup lang="ts">
// AI 审阅后台：2 tab 骨架 + 常驻模式状态条。
// 设计决策（2026-10）：AI 审阅产出只读——出题人以他人视角审阅题目，
// 审阅信息作为 AI/人工搜索依据，不再提供人工编辑/审核/黄金集机制。
// 词表治理已拆分为独立页面「标签管理」（manage-tag）：那边面向「一个概念一行」的治理，
// 与本页的流水线运维是两件事，混在 tab 里两个用途都做不深。
// 各 tab 为独立组件（总览/题目列表），
// 父组件只承担：总览数据（模式条与总览 tab 共用）、运行参数与限额弹窗、跨视图动作分发。
import { onMounted, ref } from "vue";
import { useRouter } from "vue-router";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsError, ShowTextTipsInfo, type GlobalProperties } from "@/util/tips";
import {
  GetEnrichOverview,
  GetEnrichWorkerConfig,
  PostEnrichRejudge,
  PostEnrichWorkerSettingsSet,
} from "@/apis/problem-enrichment";
import EnrichModeBar from "./EnrichModeBar.vue";
import EnrichOverviewTab from "./EnrichOverviewTab.vue";
import EnrichStateTab from "./EnrichStateTab.vue";
import type { EnrichOverview, EnrichWorkerConfig, EnrichWorkerSettings } from "@/types/problem-enrichment";

const globalProperties = useCurrentInstance().globalProperties as GlobalProperties;
const router = useRouter();

const activeTab = ref("overview");

// ── 总览数据（模式条 + 总览 tab 共用） ──
const overview = ref<EnrichOverview | null>(null);
const overviewLoading = ref(false);
const workerConfig = ref<EnrichWorkerConfig | null>(null);

const fetchWorkerConfig = async () => {
  try {
    const res = await GetEnrichWorkerConfig();
    if (res.code === 0) {
      workerConfig.value = res.data;
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
  }
};

const fetchOverview = async () => {
  overviewLoading.value = true;
  try {
    const res = await GetEnrichOverview();
    if (res.code === 0 && res.data) {
      // 后端 nil 切片会序列化为 null，统一兜底避免模板读取 .length 时渲染崩溃
      const d = res.data;
      overview.value = {
        ...d,
        today: d.today ?? { total: 0, success: 0, fail: 0, running: 0, success_tokens: 0, success_rate: 0 },
        progress: d.progress ?? {
          human_curated: 0,
          finished: 0,
          pending_total: 0,
          today_problems: 0,
          rate_per_hour: 0,
          eta_minutes: -1,
        },
        budget: d.budget ?? { token_limit: 0, token_used: 0, problem_limit: 0, problem_used: 0 },
        worker: d.worker ?? { alive: false, heartbeat_time: "", interval_seconds: 0, stale_timeout_sec: 600 },
        workers: d.workers ?? [],
        stale_workers: d.stale_workers ?? [],
        active: d.active ?? [],
        recent_failures: d.recent_failures ?? [],
        stage_latency: d.stage_latency ?? [],
      };
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
  } finally {
    overviewLoading.value = false;
  }
};

// ── 跨视图动作 ──
// dataVersion：外部动作（重判/切换模式）后递增，列表据此刷新
const dataVersion = ref(0);
const refreshAll = () => {
  dataVersion.value += 1;
  fetchOverview();
  fetchWorkerConfig();
};

// 题目列表筛选下钻（总览点击状态卡 → 切到列表并应用筛选）
const stateFilterReq = ref<{ statuses: number[]; seq: number } | null>(null);
const gotoStatus = (status: number | null) => {
  activeTab.value = "state";
  stateFilterReq.value = { statuses: status == null ? [] : [status], seq: Date.now() };
};

// ── 产出详情：统一跳转独立详情页（全宽展示、可刷新收藏） ──
const openDetail = (problemId: number, problemKey?: string) => {
  router.push({
    name: "manage-problem-enrichment-detail",
    // path 路由用题目 key（可读 URL）；入口只有 id 时以数字占位，后端做数字兜底
    params: { problemKey: problemKey || String(problemId) },
  });
};

// ── 重判（跨视图共用动作） ──
const requeue = async (problemId: number) => {
  try {
    const res = await PostEnrichRejudge(problemId);
    if (res.code === 0) {
      ShowTextTipsInfo(globalProperties, "已强制重新入队，judge 将重新处理");
      refreshAll();
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  }
};

// ── 运行参数与每日限额（弹窗编辑） ──
//
// 这些参数存在后端 kv_store，judge worker 每轮 tick 读取，因此保存后下一轮即生效，
// 不需要重启 judge。限额只约束自动批量：人工重判走独立队列，不受限额阻断。
const settingsVisible = ref(false);
const settingsSaving = ref(false);
const settingsForm = ref<EnrichWorkerSettings>({
  enabled: false,
  interval_seconds: 10,
  batch_size: 3,
  max_attempt: 3,
  stale_timeout_seconds: 600,
  daily_token_limit: 0,
  daily_problem_limit: 0,
});

const openSettings = async () => {
  // 打开时以服务端生效值为准（可能刚被别的管理员改过），失败则退回本地缓存
  await fetchWorkerConfig();
  if (workerConfig.value) {
    settingsForm.value = { ...workerConfig.value.settings };
  }
  settingsVisible.value = true;
};

const saveSettings = async () => {
  settingsSaving.value = true;
  try {
    const res = await PostEnrichWorkerSettingsSet(settingsForm.value);
    if (res.code === 0) {
      ShowTextTipsInfo(globalProperties, "运行参数已保存，worker 下一轮生效");
      settingsVisible.value = false;
      refreshAll();
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    settingsSaving.value = false;
  }
};

onMounted(() => {
  fetchWorkerConfig();
  fetchOverview();
});
</script>

<template>
  <div class="enrich-admin">
    <t-card class="enrich-header-card">
      <div class="enrich-header">
        <h2>AI 审阅后台</h2>
      </div>
      <p class="enrich-subtitle">
        摘要 / 标签 / 难度 / 质量由 AI 审阅流水线产出，审阅信息只读，供出题人以他人视角检视题目并作为检索依据。候选标签的治理（规范名与别名、人工与 AI 的边界）见「标签管理」页。
      </p>
    </t-card>

    <!-- 常驻模式状态条：运行状态 / 运行参数入口 / worker 心跳 / 今日预算 -->
    <EnrichModeBar
      :overview="overview"
      :worker-config="workerConfig"
      @open-settings="openSettings"
    />

    <t-card class="enrich-body-card">
      <t-tabs v-model="activeTab">
        <t-tab-panel value="overview" label="总览">
          <EnrichOverviewTab
            :overview="overview"
            :loading="overviewLoading"
            @refresh="fetchOverview"
            @goto-status="gotoStatus"
            @open-detail="openDetail"
            @requeue="requeue"
          />
        </t-tab-panel>

        <t-tab-panel value="state" label="题目列表">
          <EnrichStateTab
            :data-version="dataVersion"
            :filter-request="stateFilterReq"
            @open-detail="openDetail"
          />
        </t-tab-panel>
      </t-tabs>
    </t-card>

    <!-- 运行参数与每日限额：保存到后端 kv_store，judge worker 下一轮 tick 生效 -->
    <t-dialog
      v-model:visible="settingsVisible"
      header="运行参数与每日限额"
      width="560px"
      :confirm-loading="settingsSaving"
      @confirm="saveSettings"
    >
      <t-form label-align="right" label-width="120px" class="settings-form">
        <t-form-item label="启用 worker">
          <t-switch v-model="settingsForm.enabled" />
          <span class="settings-hint">关闭后不再认领任何题目（含人工重判）</span>
        </t-form-item>
        <t-form-item label="轮询间隔（秒）">
          <t-input-number v-model="settingsForm.interval_seconds" :min="5" :max="86400" />
        </t-form-item>
        <t-form-item label="每轮题数">
          <t-input-number v-model="settingsForm.batch_size" :min="1" :max="50" />
          <span class="settings-hint">人工重判与自动待办共享这个额度，人工优先</span>
        </t-form-item>
        <t-form-item label="单题最大重试">
          <t-input-number v-model="settingsForm.max_attempt" :min="1" :max="10" />
          <span class="settings-hint">超过即置失败终态，防止反复烧钱</span>
        </t-form-item>
        <t-form-item label="卡死超时（秒）">
          <t-input-number v-model="settingsForm.stale_timeout_seconds" :min="60" :max="86400" />
          <span class="settings-hint">处理中超过此时长视为 worker 卡死并回收</span>
        </t-form-item>
        <t-form-item label="每日 token 限额">
          <t-input-number v-model="settingsForm.daily_token_limit" :min="0" />
          <span class="settings-hint">0 表示不限制</span>
        </t-form-item>
        <t-form-item label="每日题数限额">
          <t-input-number v-model="settingsForm.daily_problem_limit" :min="0" />
          <span class="settings-hint">0 表示不限制</span>
        </t-form-item>
      </t-form>
      <p class="settings-note">
        限额只约束自动审阅：人工重判走独立队列，即使当日限额已用尽也会照常处理（仍计入当日用量统计）。
      </p>
    </t-dialog>
  </div>
</template>

